describe('Mobile Responsive - Sauce Demo Store', () => {
  beforeEach(() => {
    cy.viewport(375, 812);
    cy.visit('https://www.saucedemo.com');
  });

  it('should display inventory page after login on mobile viewport', () => {
    cy.get('[data-test="username"]').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();

    cy.url().should('include', '/inventory.html');
    cy.get('.inventory_list').should('be.visible');
    cy.get('.inventory_item').should('have.length.greaterThan', 0);
  });

  it('should display burger menu button and open side menu with logout link', () => {
    cy.get('[data-test="username"]').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();

    cy.get('#react-burger-menu-btn').should('be.visible');
    cy.get('#react-burger-menu-btn').click();

    cy.get('.bm-menu').should('be.visible');
    cy.get('#logout_sidebar_link').should('be.visible');
  });

  it('should handle logout from side menu on mobile', () => {
    cy.get('[data-test="username"]').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();

    cy.get('#react-burger-menu-btn').click();
    cy.get('.bm-menu').should('be.visible');
    cy.get('#logout_sidebar_link').click();

    cy.url().should('include', '/');
    cy.get('[data-test="login-button"]').should('be.visible');
  });

  it('should maintain responsive layout when scrolling inventory on mobile', () => {
    cy.get('[data-test="username"]').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();

    cy.get('.inventory_list').should('be.visible');
    cy.get('.inventory_list').scrollTo('bottom');

    cy.get('#react-burger-menu-btn').should('be.visible');
    cy.get('.inventory_item').should('have.length.greaterThan', 0);
  });
});
